function sum(numbers) {
  let total = 0;
  for (const n of numbers) {
    total = total + 1; // ovde
  }
  return total;
}

answer:
function sum(numbers) {
  let total = 0;
  for (const n of numbers) {
    total = total + n;
  }
  return total;
}
